</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
#include <algorithm>
using namespace std;

int totalN, totalK, modVal;
long long factArr[250003], invFactArr[250003];
long long memoTable[27][250003];

int getBit(int x) { return x & (-x); }

long long modPow(long long base, int exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % modVal;
        base = (base * base) % modVal;
        exp >>= 1;
    }
    return res;
}

void precomputeValues() {
    factArr[0] = 1;
    for (int i = 1; i <= totalN; ++i)
        factArr[i] = (factArr[i - 1] * i) % modVal;
    invFactArr[totalN] = modPow(factArr[totalN], modVal - 2);
    for (int i = totalN - 1; i >= 0; --i)
        invFactArr[i] = (invFactArr[i + 1] * (i + 1)) % modVal;
}

long long recursiveDP(int x, int s) {
    if (memoTable[x][s] != -1) return memoTable[x][s];
    if (s == 0) return memoTable[x][s] = (factArr[totalN] * factArr[totalK] % modVal) * invFactArr[totalK - x] % modVal;
    int remaining = s - getBit(s);
    long long sumRes = 0;
    for (int t = remaining; t; t = (t - 1) & remaining)
        sumRes = (sumRes + recursiveDP(x + 1, t) * invFactArr[s - t]) % modVal;
    sumRes = (sumRes + recursiveDP(x + 1, 0) * invFactArr[s]) % modVal;
    return memoTable[x][s] = sumRes;
}

int main() {
    scanf("%d %d %d", &totalN, &totalK, &modVal);
    precomputeValues();
    long long ans = modPow(totalK, totalN);
    if (totalN % 2 == 0) {
        memset(memoTable, -1, sizeof(memoTable));
        ans = (ans - recursiveDP(0, totalN) + modVal) % modVal;
    }
    printf("%lld", ans);
    return 0;
}
